const dbToLin = (db) => Math.pow(10, db / 20);
const linToDb = (x) => 20 * Math.log10(Math.max(x, 1e-6));
const coef = (ms) => Math.exp(-1 / ((Math.max(ms, 0.05) / 1000) * sampleRate));

